/**
 * Indent each line of a string by a number of spaces (blank lines stay blank).
 * @param {string} text
 * @param {number} [spaces]
 */
export function indent(text, spaces = 2) {
  const prefix = " ".repeat(spaces);
  return text.split("\n").map((line) => (line ? prefix + line : line)).join("\n");
}

/**
 * Remove leading and trailing blank lines.
 * @param {string} text
 */
export function trimBlankLines(text) {
  const lines = text.split("\n");
  while (lines.length > 0 && lines[0]?.trim() === "") lines.shift();
  while (lines.length > 0 && lines[lines.length - 1]?.trim() === "") lines.pop();
  return lines.join("\n");
}

/**
 * Wrap text at a line length (words are never split).
 * @param {string} text
 * @param {number} [maxLength]
 */
export function wrapText(text, maxLength = 80) {
  const lines = [];
  let currentLine = "";
  for (const word of text.split(" ")) {
    if (currentLine.length + word.length + 1 <= maxLength) {
      currentLine += (currentLine ? " " : "") + word;
    } else {
      if (currentLine) lines.push(currentLine);
      currentLine = word;
    }
  }
  if (currentLine) lines.push(currentLine);
  return lines.join("\n");
}

/**
 * Escape a string for a JavaScript string literal.
 * @param {string} text
 */
export function escapeString(text) {
  return text
    .replace(/\\/g, "\\\\")
    .replace(/'/g, "\\'")
    .replace(/"/g, '\\"')
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r")
    .replace(/\t/g, "\\t");
}

/**
 * A valid identifier from any string.
 * @param {string} text
 */
export function toIdentifier(text) {
  return text
    .replace(/[^a-zA-Z0-9_]/g, "_")
    .replace(/^(\d)/, "_$1")
    .replace(/__+/g, "_")
    .replace(/^_|_$/g, "");
}

/**
 * Pluralize a word (simple English rules).
 * @param {string} word
 * @param {number} [count]
 */
export function pluralize(word, count) {
  if (count === 1) return word;
  if (word.endsWith("s") || word.endsWith("x") || word.endsWith("ch") || word.endsWith("sh")) return word + "es";
  if (word.endsWith("y") && !/[aeiou]y$/i.test(word)) return word.slice(0, -1) + "ies";
  return word + "s";
}

/**
 * Singularize a word (simple English rules).
 * @param {string} word
 */
export function singularize(word) {
  if (word.endsWith("ies")) return word.slice(0, -3) + "y";
  if (word.endsWith("es") && (word.endsWith("ses") || word.endsWith("xes") || word.endsWith("ches") || word.endsWith("shes"))) {
    return word.slice(0, -2);
  }
  if (word.endsWith("s") && !word.endsWith("ss")) return word.slice(0, -1);
  return word;
}

/**
 * The header comment of every generated file.
 * @param {string} generatorName e.g. "kit sdk generate (@saasreport/forge)"
 * @param {string} [comment] the line-comment prefix of the target language ("//", "#")
 * @returns {string}
 */
export function generatedFileHeader(generatorName, comment = "//") {
  return `${comment} Generated by ${generatorName} transformer
${comment} DO NOT EDIT - This file is auto-generated
`;
}
